/**
 * @module O 内容工具箱
 *
 * enemy.template 投影器——把 Resource Graph 中的 enemy.template 节点投影回
 * oblivions/gamedata/enemies_config.php 的 `return [...]` 标准形态。
 *
 * 设计意图（执行案 06-P5 §4.4 / §4.3.2）：
 * - P5 单源编译阶段把 enemies_config.php 从 `$obl_enemies_config = array(...)`
 *   全局变量赋值形态改造为 `return [...]` 标准形态——与 oblivions/gamedata 其他
 *   根级 PHP 文件格式统一，降低 codegen 复杂度。
 * - 同步修改 init.func.php:282-283 的消费方：`$obl_enemies_config = include ...`
 *   （保留 `if (!isset(...))` 包裹，维持按需加载语义）。
 * - 投影器使用 P5-2 新 API generatePhpFile（schema projectionTargets 派生）：
 *     * 文件头注入 `// AUTO-GENERATED FROM oblivions/content/...` 只读保护注释
 *     * @module 标签由 schema.projectionTargets[0].module 派生（'E 游戏逻辑'）
 *     * 节标题块注释由 sectionTitle 派生
 *   不再使用硬编码文件头模板。
 * - 顶层 key 是数字（敌人类型 ID），PHP codegen 通过 renderPhpKey 的"数字字符串
 *   key 直接输出为数字（不加引号）"机制保留数字 key 形态。
 * - strategy_slots 是 4 槽数组，每槽可为 null 或 {type:'skill', id:'...'}——
 *   null 槽位必须保留（与 schema default `[null, null, null, null]` 对齐）。
 *
 * 字段映射（节点 data → enemies_config.php entry）：
 *   - 节点 id（数字字符串）          → 顶层数字 key
 *   - data.name                      → 'name' 字段（P5 仍保留，过渡期后由 presentation.enemy 投影）
 *   - data.icon / gd                 → 'icon' / 'gd' 字段
 *   - data.hp / mhp / sp / msp / att / def / lvl → 战斗属性字段
 *   - data.ai_type / vision_range / action_chance → AI 字段
 *   - data.skills[] / combat_skills[] → 字符串数组字段
 *   - data.strategy_slots[]          → 4 槽结构数组字段（保留 null 槽位）
 *
 * 边界：
 * - 节点 data 为 null/非对象时跳过该节点（不写入字典）
 * - undefined 字段递归移除（与 php-adapter.stripUndefinedFields 对齐）
 * - 保留所有显式值（含 false / 0 / '' / null），保证 round-trip 一致性
 * - 节点 id 必须匹配 /^[1-9]\d*$/，否则跳过（idPattern 校验）
 * - 顶层 key 顺序按节点数组顺序保留（vuedraggable 拖拽后写入图，投影时按图顺序输出）
 *
 * 集成：
 * - php-adapter.serializePhpResource 路由到本投影器（当 kind='enemy.template' 时）
 * - BuildView 在发布前通过 serializeNodes 间接调用本投影器生成 PublishableFile
 */

import { generatePhpFile, type PhpValue } from '../../shared/serializer/php-codegen';
import type { ResourceNode } from '../../graph/types';
import type { SerializedPhpFile } from '../../adapters/php-adapter';

/** 目标文件路径（工作区相对路径） */
const ENEMIES_CONFIG_FILE_PATH = 'oblivions/gamedata/enemies_config.php';

/** 作者资源 YAML 路径——用于 AUTO-GENERATED 注释 */
const ENEMIES_CONFIG_AUTHOR_SOURCE = 'oblivions/content/enemies/enemies.yaml';

/** enemy.template 节点 id 正则——与 schema idPattern 对齐 */
const ENEMY_TEMPLATE_ID_PATTERN = /^[1-9]\d*$/;

/** enemy.template 节点 data 期望形态（与 enemy-template.ts schema 字段 key 对齐） */
interface EnemyTemplateData {
  name?: string;
  icon?: string;
  gd?: string;
  hp?: number;
  mhp?: number;
  sp?: number;
  msp?: number;
  att?: number;
  def?: number;
  lvl?: number;
  ai_type?: string;
  vision_range?: number;
  action_chance?: number;
  skills?: string[];
  combat_skills?: string[];
  strategy_slots?: Array<{ type: string; id: string } | null>;
  [key: string]: unknown;
}

/**
 * 把 enemy.template 节点投影回 enemies_config.php 形态（P5 `return [...]` 标准形态）。
 *
 * @param nodes enemy.template 节点数组（顺序保留为顶层 key 顺序）
 * @returns 单个 SerializedPhpFile（filePath 指向 oblivions/gamedata/enemies_config.php）
 */
export function projectEnemiesConfig(nodes: ResourceNode[]): SerializedPhpFile[] {
  const dict = buildEnemiesConfigDict(nodes);
  const content = generatePhpFile(dict, {
    module: 'E 游戏逻辑',
    sectionTitle: 'Oblivions 敌人模板配置',
    autoGeneratedFrom: ENEMIES_CONFIG_AUTHOR_SOURCE,
  });
  return [{ filePath: ENEMIES_CONFIG_FILE_PATH, content }];
}

/**
 * 把 enemy.template 节点重建为 enemies_config.php 字典形态。
 *
 * 输出形态：`{ 1 => {...}, 2 => {...} }`，key 是数字（通过 renderPhpKey 数字字符串
 * key 不加引号机制保留），value 是各字段的关联数组。
 *
 * 字段顺序按 schema fields 顺序保留——敌人 1 与敌人 2 在原文件中字段顺序一致，
 * 投影器按固定字段顺序输出，保证 round-trip 一致性。
 *
 * strategy_slots 4 槽结构数组：保留 null 槽位（与 schema default 对齐），
 * 非空槽位输出 `['type' => 'skill', 'id' => '...']` 形态。
 */
function buildEnemiesConfigDict(nodes: ResourceNode[]): PhpValue {
  const dict: Record<string, PhpValue> = {};
  for (const node of nodes) {
    if (!ENEMY_TEMPLATE_ID_PATTERN.test(node.id)) continue;
    if (node.data === null || typeof node.data !== 'object' || Array.isArray(node.data)) {
      continue;
    }
    const cleaned = stripUndefinedFields(node.data) as EnemyTemplateData;
    // 按字段顺序输出（与原文件 enemies_config.php 字段顺序对齐）
    const entry: Record<string, PhpValue> = {};
    if (cleaned.name !== undefined) entry.name = cleaned.name;
    if (cleaned.icon !== undefined) entry.icon = cleaned.icon;
    if (cleaned.gd !== undefined) entry.gd = cleaned.gd;
    if (cleaned.hp !== undefined) entry.hp = cleaned.hp;
    if (cleaned.mhp !== undefined) entry.mhp = cleaned.mhp;
    if (cleaned.sp !== undefined) entry.sp = cleaned.sp;
    if (cleaned.msp !== undefined) entry.msp = cleaned.msp;
    if (cleaned.att !== undefined) entry.att = cleaned.att;
    if (cleaned.def !== undefined) entry.def = cleaned.def;
    if (cleaned.lvl !== undefined) entry.lvl = cleaned.lvl;
    if (cleaned.ai_type !== undefined) entry.ai_type = cleaned.ai_type;
    if (cleaned.vision_range !== undefined) entry.vision_range = cleaned.vision_range;
    if (cleaned.action_chance !== undefined) entry.action_chance = cleaned.action_chance;
    if (cleaned.skills !== undefined) entry.skills = cleaned.skills as PhpValue;
    if (cleaned.combat_skills !== undefined) entry.combat_skills = cleaned.combat_skills as PhpValue;
    if (cleaned.strategy_slots !== undefined) {
      entry.strategy_slots = cleaned.strategy_slots as PhpValue;
    }
    dict[node.id] = entry;
  }
  return dict;
}

/**
 * 递归移除 undefined 字段（与 php-adapter.stripUndefinedFields 行为一致）。
 *
 * 保留所有显式值（含 false / 0 / '' / null），仅移除 undefined。
 * 用于序列化时对齐原文件省略字段的契约。
 */
function stripUndefinedFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedFields);
  }
  if (value !== null && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue;
      result[k] = stripUndefinedFields(v);
    }
    return result;
  }
  return value;
}
